func checkInclusion(_ s1: String, _ s2: String) -> Bool {
    let a = Array(s1.utf8), b = Array(s2.utf8)
    guard a.count <= b.count else { return false }
    var need = [Int](repeating: 0, count: 26), have = need
    for c in a { need[Int(c - 97)] += 1 }
    for i in b.indices {
        have[Int(b[i] - 97)] += 1
        if i >= a.count { have[Int(b[i - a.count] - 97)] -= 1 }
        if have == need { return true }
    }
    return false
}
